// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0));
        // first call should succeed (addReward does not revert)
        c.addReward(token);
        // second call with same token should revert because token already added
        vm.expectRevert("exists");
        c.addReward(token);
        // If we reach here, first call succeeded and second reverted as expected
        assertTrue(true);
    }
}

